{
  "ledger": {
    "p60:e461": {
      "state": "no_research",
      "fact_ids": [],
      "note": "\"+\"는 단순 연결 기호로 연구 내용 없음."
    },
    "p60:e462": {
      "state": "represented",
      "fact_ids": ["P0060F0001"],
      "note": "커널 memcpy에서 MAXDIM 512 float 복사를 필요한 만큼만 복사하도록 수정했으나 CPU 계산 오버헤드로 시간이 늘었다는 내용이 P0060F0001에 보존됨."
    },
    "p60:e463": {
      "state": "no_research",
      "fact_ids": [],
      "note": "\"예를 들어 이런 거,\"는 전환 문구로 연구 내용 없음."
    },
    "p60:e464": {
      "state": "no_research",
      "fact_ids": [],
      "note": "\"자세한 내용은 아래 문서 링크 참조\"는 링크 참조 문구로 실제 보존된 내용 없음."
    },
    "p60:e465": {
      "state": "no_research",
      "fact_ids": [],
      "note": "\"단일 샘플 빠르게 입력\"은 섹션 제목으로 연구 내용 없음."
    },
    "p60:e466": {
      "state": "raw_data",
      "fact_ids": [],
      "note": "차트에 backward_cuda_graph 123, forward_cuda_graph 100646 값이 있으나 승인된 사실에 반영되지 않아 원시 데이터로 보존. 표(p60:enh:e8)의 수치와도 다른 별도 시각화 값."
    },
    "p60:e467": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "forward_cuda_graph 983s 전체 시간, 1055가 CPU에서 필요한 만큼 계산 후 복사한 시간, 72초 차이(더 느려짐)라는 구체적 수치가 승인된 사실에 없음. 일반론적 '시간 증가'만 P0060F0001에 보존됨."
    },
    "p60:enh:e0": {
      "state": "represented",
      "fact_ids": ["P0060F0003", "P0060F0005"],
      "note": "cudaHostRegister로 데이터셋 메모리를 pinned memory로 등록하는 코드(N>0 조건, cudaHostRegisterDefault 플래그, 성공/실패 시 출력)가 P0060F0003, P0060F0005에 보존됨."
    },
    "p60:enh:e1": {
      "state": "no_research",
      "fact_ids": [],
      "note": "\"+\"는 단순 연결 기호로 연구 내용 없음."
    },
    "p60:enh:e2": {
      "state": "represented",
      "fact_ids": ["P0060F0001"],
      "note": "MAXDIM으로 무조건 512 float 복사하던 것을 고쳤다는 내용이 P0060F0001에 보존됨."
    },
    "p60:enh:e3": {
      "state": "represented",
      "fact_ids": ["P0060F0001"],
      "note": "필요한 만큼만 복사했으나 CPU 계산 오버헤드가 더 큰 것 같고 시간이 늘었다는 내용이 P0060F0001에 보존됨."
    },
    "p60:enh:e4": {
      "state": "represented",
      "fact_ids": ["P0060F0002"],
      "note": "out_bytes = sizeof(int) + out_dim * sizeof(float)로 계산하여 cudaMemcpyAsync로 d_final_lower, d_final_upper를 Host로 복사하고 cudaStreamSynchronize(stream) 수행하는 코드가 P0060F0002에 보존됨."
    },
    "p60:enh:e5": {
      "state": "no_research",
      "fact_ids": [],
      "note": "\"예를 들어 이런 거,\"는 전환 문구로 연구 내용 없음."
    },
    "p60:enh:e6": {
      "state": "no_research",
      "fact_ids": [],
      "note": "\"자세한 내용은 아래 문서 링크 참조\"는 링크 참조 문구로 실제 보존된 내용 없음."
    },
    "p60:enh:e7": {
      "state": "no_research",
      "fact_ids": [],
      "note": "\"단일 샘플 빠르게 입력\"은 섹션 제목으로 연구 내용 없음."
    },
    "p60:enh:e8": {
      "state": "raw_data",
      "fact_ids": [],
      "note": "structured_table_manifest에 complete=true로 등록된 표. 행별 수치(forward_cuda_graph 983.5557, backward_cuda_graph 1134.724, forward_cuda_graph_fused 1006.863 등 6행)는 원시 데이터로 보존. 승인된 사실에 표 수치 연결 없음."
    },
    "p60:enh:e9": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "forward_cuda_graph가 983s 정도 전체 시간, 아래 1055가 CPU에서 필요한 만큼 계산 후 복사한 시간이라는 구체적 수치가 승인된 사실에 없음."
    },
    "p60:enh:e10": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "72초 차이(더 늦어짐)라는 구체적 수치가 승인된 사실에 없음."
    },
    "p60:enh:e11": {
      "state": "no_research",
      "fact_ids": [],
      "note": "\"일단 마지막 1055의 자세한 측정 결과를 보면\"은 다음 내용으로 연결하는 문구로 연구 내용 없음."
    }
  }
}
